package main

import (
	"errors"
	"fmt"
	"sync"
)

func main() {
	sem := make(chan struct{}, 2)
	var wg sync.WaitGroup
	for i := 1; i <= 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			if err := check(i); err != nil {
				fmt.Println("task", i, "failed:", err)
				return
			}
			fmt.Println("task", i, "ok")
			<-sem
		}()
	}
	wg.Wait()
	fmt.Println("done")
}

func check(i int) error {
	if i > 0 {
		return errors.New("bad input")
	}
	return nil
}

package main

import "fmt"

type result struct{ job, square int }

func main() {
	jobs := make(chan int)
	results := make(chan result)
	for w := 1; w <= 3; w++ {
		go func() {
			for n := range jobs {
				results <- result{n, n * n}
			}
		}()
	}
	for n := 1; n <= 9; n++ {
		jobs <- n
	}
	close(jobs)
	sum := 0
	for r := range results {
		sum += r.square
	}
	fmt.Println(sum)
}
